 P("Collapse long messages","Messages","Add expand/collapse for long messages","(()=>{const add=()=>document.querySelectorAll('[class*=messageContent]').forEach(e=>{if(e.dataset.nxcl||e.innerText.length<600)return;e.dataset.nxcl=1;e.style.maxHeight='180px';e.style.overflow='hidden';let b=document.createElement('button');b.textContent='Expand';b.onclick=()=>{let open=e.dataset.open==='1';e.dataset.open=open?'0':'1';e.style.maxHeight=open?'180px':'none';b.textContent=open?'Expand':'Collapse'};e.after(b)});add();new MutationObserver(add).observe(document.body,{childList:true,subtree:true})})()"),
 P("Message word counts","Messages","Show word count on hover","document.querySelectorAll('[class*=messageContent]').forEach(e=>e.title=e.innerText.trim().split(/\\s+/).filter(Boolean).length+' words')"),
 P("Floating chat jump buttons","Navigation","Add fixed jump-to-top and bottom controls","(()=>{if(document.getElementById('nx-jump'))return;let box=document.createElement('div');box.id='nx-jump';box.style.cssText='position:fixed;right:16px;bottom:90px;z-index:99999;display:grid;gap:6px';['↑','↓'].forEach((t,i)=>{let b=document.createElement('button');b.textContent=t;b.style.cssText='border:0;border-radius:24px;padding:9px 13px;background:#5865f2;color:white;font-size:18px';b.onclick=()=>document.querySelector('[class*=messagesWrapper]')?.scrollTo({top:i?999999:0,behavior:'smooth'});box.append(b)});document.body.append(box)})()"),
 P("Reveal spoilers on click","Privacy","Make spoiler text click-to-reveal","document.querySelectorAll('[class*=spoiler]').forEach(e=>{if(e.dataset.nxrev)return;e.dataset.nxrev=1;e.style.filter='blur(5px)';e.style.cursor='pointer';e.onclick=()=>e.style.filter='none'})"),
 P("Highlight code keywords","Developer","Highlight common code keywords locally","(()=>{let s=document.createElement('style');s.dataset.nexora='1';s.textContent='pre .keyword,pre .token.keyword{color:#c792ea!important;font-weight:600}';document.head.append(s)})()"),
 P("Message reading mode","Accessibility","Remove clutter around message content","(()=>{let s=document.createElement('style');s.dataset.nexora='1';s.textContent='[class*=messageContent]{font-size:16px!important;line-height:1.7!important;max-width:80ch!important}[class*=messageListItem]{padding:8px 0!important}';document.head.append(s)})()"),
 P("Copy channel link helper","Navigation","Add copy URL control to channel header","(()=>{let h=document.querySelector('[class*=chatHeader]');if(!h||h.dataset.nxurl)return;h.dataset.nxurl=1;let b=document.createElement('button');b.textContent='Copy channel URL';b.onclick=()=>navigator.clipboard.writeText(location.href).then(()=>b.textContent='Copied');h.append(b)})()"),
 P("Hide message action bar","Interface","Hide message hover toolbar",css("[class*=buttonContainer]{display:none!important}")),
 P("Hide reply quote","Messages","Hide reply preview cards",css("[class*=repliedMessage]{display:none!important}"))
 )
 fun open(){AlertDialog.Builder(activity).setTitle("NEXORA functional plugin library ("+list.size+")").setItems(arrayOf("Browse categories","Search","Installed plugins","Safety info")){_,i->when(i){0->cats();1->search();2->installed();else->info()}}.setNegativeButton("Close",null).show()}
 private fun data()=try{JSONArray(prefs.getString("custom_plugins","[]"))}catch(_:Exception){JSONArray()}
 private fun cats(){val c=list.map{it.cat}.distinct().sorted();AlertDialog.Builder(activity).setTitle("Categories").setItems(c.toTypedArray()){_,i->browse(list.filter{it.cat==c[i]})}.setNegativeButton("Back",null).show()}
 private fun search(){val e=EditText(activity).apply{hint="Search plugins"};AlertDialog.Builder(activity).setTitle("Search").setView(e).setPositiveButton("Find"){_,_->val q=e.text.toString().lowercase();browse(list.filter{it.name.lowercase().contains(q)||it.desc.lowercase().contains(q)||it.cat.lowercase().contains(q)})}.setNegativeButton("Cancel",null).show()}
 private fun browse(a:List<P>){if(a.isEmpty()){Toast.makeText(activity,"No results",0).show();return};AlertDialog.Builder(activity).setTitle("Select plugin ("+a.size+")").setItems(a.map{it.name+" • "+it.desc}.toTypedArray()){_,i->install(a[i])}.setNegativeButton("Back",null).show()}
 private fun install(p:P){AlertDialog.Builder(activity).setTitle(p.name).setMessage(p.cat+"\n"+p.desc+"\n\nRuns locally in Discord WebView.").setPositiveButton("Install"){_,_->val a=data();val source="builtin:nexora:"+p.name;val existing=(0 until a.length()).firstOrNull{a.optJSONObject(it)?.optString("source","")==source};if(existing!=null){val old=a.optJSONObject(existing)!!;old.put("enabled",true);prefs.edit().putString("custom_plugins",a.toString()).apply();Toast.makeText(activity,p.name+" already installed; enabled it.",1).show();onInstalled();return@setPositiveButton};a.put(JSONObject().put("name","NEXORA • "+p.name).put("source",source).put("code",p.code).put("enabled",true));val err=PluginStoragePolicy.validate(a);if(err!=null){Toast.makeText(activity,err,1).show();return@setPositiveButton};prefs.edit().putString("custom_plugins",a.toString()).apply();Toast.makeText(activity,"Installed "+p.name+"; reload…",1).show();onInstalled()}.setNegativeButton("Cancel",null).show()}
 private fun installed(){val a=data();val ix=(0 until a.length()).filter{a.optJSONObject(it)?.optString("source","")?.startsWith("builtin:nexora:")==true};if(ix.isEmpty()){Toast.makeText(activity,"No built-ins installed",0).show();return};AlertDialog.Builder(activity).setTitle("Installed").setItems(ix.map{a.optJSONObject(it)?.optString("name")?:"Plugin"}.toTypedArray()){_,i->val n=ix[i];val p=a.optJSONObject(n)!!;AlertDialog.Builder(activity).setTitle(p.optString("name")).setItems(arrayOf(if(p.optBoolean("enabled",true))"Disable" else "Enable","Delete")){_,j->if(j==0)p.put("enabled",!p.optBoolean("enabled",true))else a.remove(n);prefs.edit().putString("custom_plugins",a.toString()).apply();onInstalled();installed()}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Back",null).show()}
 private fun info(){AlertDialog.Builder(activity).setTitle("Plugin safety").setMessage("These are actual executable WebView add-ons and can access page/session data. Effects are local only; they do not grant Nitro, badges or permissions. Disable/delete in Installed plugins.").setPositiveButton("OK",null).show()}
}